      "title": "Warn from (tokens)",
      "default": 200000,
      "description": "Context size at which the token count turns yellow, the ⚠2x long-context tag appears, and a toast fires once"
    },
    "dangerTokens": {
      "type": "number",
      "title": "Danger from (tokens)",
      "default": 300000,
