    },
    "compactAt": {
      "type": "number",
      "title": "Compact at (tokens)",
      "default": 0,
      "description": "Context size that triggers a compaction after the turn that crossed it; 0 turns it off"
    },
    "compactConfirm": {
      "type": "boolean",
      "title": "Ask before compacting",
      "default": true,
      "description": "A Compact / Later question before the compaction compactAt or the compact button triggers"
